// The status function needs only the authenticated user's app role. Bind the
// SDK client to the reviewed app and official API, without service authority or
// forwarding caller-supplied app/API routing headers.
export function createBoundAppUserReader(projectRef, createClient) {
  if (typeof createClient !== 'function') throw new Error('SDK_CLIENT_REQUIRED');
  const appId = /^base44:([a-f0-9]{24})$/.exec(projectRef ?? '')?.[1];
  return async request => {
    if (!appId) throw Object.assign(new Error('APP_BINDING_REQUIRED'), { status: 503 });
    const token = /^Bearer ([^\s]+)$/.exec(request.headers.get('authorization') ?? '')?.[1];
    if (!token) throw Object.assign(new Error('SIGN_IN_REQUIRED'), { status: 401 });
    const client = createClient({ appId, serverUrl: 'https://base44.app', token });
    try { return await client.auth.me(); }
    finally { client.cleanup?.(); }
  };
}

import { createClient } from 'npm:@base44/sdk';
import { secrets } from 'base44:runtime';
import { createAppStatusBackend } from './handler.js';
import { createBoundAppUserReader } from './auth.js';

// Native Base44 fills these literals from the independently verified exact
// app-surface plan. Unconfigured templates cannot read Secrets or call Cloud BOS.
const binding = Object.freeze({ enabled: false, project_ref: '', status_url: '' });

export default createAppStatusBackend(binding, {
  getUser: createBoundAppUserReader(binding.project_ref, createClient),
  readSecret: (name: string) => secrets.get(name),
});

// Copy with entry.ts only through the exact, approved target-app source plan.
// No module-level secrets, persistence, writes, service-role access or logging.
const SLOTS = Object.freeze({ A: 'BOS_APP_STATUS_A', B: 'BOS_APP_STATUS_B' });
const TOKEN = /^bos_status_[A-Za-z0-9_-]{43}$/;
const TIERS = new Set(['STANDARD', 'PLUS', 'PRO', 'ENTERPRISE', 'CREATOR_ADMIN']);
const GOVERNANCE = new Set(['GOVERNED_ACTIVE', 'STALE_OR_DRIFTED', 'UNBOUND', 'DETACHED_OR_REMOVED', 'UNKNOWN']);
const HEADERS = { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer' };
const reply = (status, http = 200, fields = {}) => new Response(JSON.stringify({
  schema: 'BOS_BASE44_APP_STATUS_BACKEND_V1', status, ...fields,
}), { status: http, headers: HEADERS });
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const exactKeys = (value, keys) => object(value) && Object.keys(value).length === keys.length && keys.every(key => Object.hasOwn(value, key));
const stopIfAborted = signal => { if (signal.aborted) throw new Error('STOPPED'); };
const fingerprint = async value => Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value))), byte => byte.toString(16).padStart(2, '0')).join('');

async function boundedJson(message, maximum, signal) {
  if (message.headers.get('content-type')?.split(';', 1)[0].trim().toLowerCase() !== 'application/json') {
    void message.body?.cancel().catch(() => {});
    throw new Error('INVALID_JSON');
  }
  const reader = message.body?.getReader();
  if (!reader) throw new Error('NO_BODY');
  const cancel = () => { void reader.cancel().catch(() => {}); };
  signal.addEventListener('abort', cancel, { once: true });
  const chunks = []; let size = 0;
  try {
    while (true) {
      stopIfAborted(signal);
      const { value, done } = await reader.read();
      stopIfAborted(signal);
      if (done) break;
      size += value.byteLength;
      if (size > maximum) { cancel(); throw new Error('BODY_TOO_LARGE'); }
      chunks.push(value);
    }
    const bytes = new Uint8Array(size); let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
    try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)); }
    catch { throw new Error('MALFORMED_JSON'); }
  } finally { signal.removeEventListener('abort', cancel); reader.releaseLock(); }
}

// Explicit projection prevents upstream diagnostics or future private fields
// from becoming part of the customer response. Dates retain their actual scope.
function projectStatus(data, projectRef, now) {
  if (!object(data) || data.schema !== 'BOS_PUBLIC_APP_STATUS_V1'
    || data.project_ref !== projectRef || !['CONNECTED', 'NEEDS_ATTENTION'].includes(data.status)
    || data.platform_connection_state !== 'CONNECTED' || !GOVERNANCE.has(data.project_governance_state)
    || typeof data.project_binding_verified !== 'boolean' || !TIERS.has(data.tier)
    || typeof data.service_version !== 'string' || !/^[0-9]+\.[0-9]+\.[0-9]+(?:[-+][A-Za-z0-9.-]+)?$/.test(data.service_version) || data.service_version.length > 80
    || data.grants_build_or_paid_access !== false
    || !object(data.governance_evidence) || data.governance_evidence.scope !== 'STORED_PROVIDER_VERIFICATION_RECORD'
    || data.governance_evidence.source_reread_this_request !== false) throw new Error('INVALID_STATUS');
  if (typeof data.observed_at !== 'string' || !(data.governance_evidence.last_verified_at === null
    || typeof data.governance_evidence.last_verified_at === 'string')) throw new Error('INVALID_DATES');
  const observed = Date.parse(data.observed_at);
  const evidence = data.governance_evidence;
  const verified = evidence.last_verified_at === null ? null : Date.parse(evidence.last_verified_at);
  if (!Number.isFinite(observed) || observed > now + 60000 || observed < now - 60000
    || (verified !== null && (!Number.isFinite(verified) || verified > observed))) throw new Error('INVALID_DATES');
  const active = data.status === 'CONNECTED';
  if (active !== data.project_binding_verified || (active && (data.project_governance_state !== 'GOVERNED_ACTIVE' || verified === null))) throw new Error('CONFLICTING_STATUS');
  return {
    schema: data.schema, status: data.status, project_ref: projectRef,
    observed_at: new Date(observed).toISOString(), service_version: data.service_version, tier: data.tier,
    platform_connection_state: data.platform_connection_state,
    project_governance_state: data.project_governance_state, project_binding_verified: active,
    governance_evidence: { scope: evidence.scope,
      last_verified_at: verified === null ? null : new Date(verified).toISOString(), source_reread_this_request: false },
    grants_build_or_paid_access: false,
  };
}

function configured(binding) {
  try {
    const url = new URL(binding.status_url);
    return binding.enabled === true && /^base44:[a-f0-9]{24}$/.test(binding.project_ref)
      && url.protocol === 'https:' && url.pathname === '/mcp/app-status'
      && !url.username && !url.password && !url.search && !url.hash && !url.port;
  } catch { return false; }
}

export function createAppStatusBackend(binding, dependencies) {
  // Freeze a copy: later caller mutation cannot retarget an already-bound handler.
  const target = Object.freeze({ ...binding });
  const { getUser, readSecret, fetch: send = globalThis.fetch, now = Date.now, timeoutMs = 8000 } = dependencies;
  if (typeof getUser !== 'function' || typeof readSecret !== 'function' || typeof send !== 'function'
    || typeof now !== 'function' || !Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 8000) throw new Error('INVALID_BACKEND_DEPENDENCIES');

  return async request => {
    if (request.method !== 'POST') return reply('METHOD_NOT_ALLOWED', 405);
    if (new URL(request.url).search) return reply('INVALID_REQUEST', 400, { diagnostic_code: 'URL_QUERY_REJECTED' });
    if (!configured(target)) return reply('STATUS_SETUP_REQUIRED', 503);
    const controller = new AbortController();
    const { signal } = controller;
    let timer; let settleTimeout;
    const interrupted = new Promise(resolve => { settleTimeout = () => { controller.abort(); resolve(reply('STATUS_UNAVAILABLE', 503)); }; });
    const onAbort = () => settleTimeout();
    request.signal.addEventListener('abort', onAbort, { once: true });
    timer = setTimeout(settleTimeout, timeoutMs);
    if (request.signal.aborted) onAbort();
    const run = async () => {
      stopIfAborted(signal);
      let user;
      try { user = await getUser(request); }
      catch (error) {
        if (error?.status === 401 || error?.response?.status === 401) return reply('SIGN_IN_REQUIRED', 401);
        if (error?.status === 403 || error?.response?.status === 403) return reply('OWNER_ADMIN_REQUIRED', 403);
        return reply('AUTHENTICATION_UNAVAILABLE', 503);
      }
      stopIfAborted(signal);
      if (!user || typeof user.id !== 'string' || !user.id) return reply('SIGN_IN_REQUIRED', 401);
      if (user.role !== 'admin') return reply('OWNER_ADMIN_REQUIRED', 403);
      let input;
      try { input = await boundedJson(request, 1024, signal); }
      catch (error) {
        // Controlled branch codes only: never echo headers, values or errors.
        const codes = { INVALID_JSON: 'CONTENT_TYPE_REJECTED', NO_BODY: 'BODY_UNAVAILABLE', BODY_TOO_LARGE: 'BODY_TOO_LARGE', MALFORMED_JSON: 'MALFORMED_JSON' };
        return reply('INVALID_REQUEST', 400, { diagnostic_code: Object.hasOwn(codes, error?.message) ? codes[error.message] : 'BODY_READ_FAILED' });
      }
      stopIfAborted(signal);
      if (!(exactKeys(input, ['action']) && input.action === 'STATUS')
        && !(exactKeys(input, ['action', 'slot']) && input.action === 'FINGERPRINT' && Object.hasOwn(SLOTS, input.slot))) return reply('INVALID_REQUEST', 400, { diagnostic_code: 'BODY_SHAPE_REJECTED' });
      const base = { project_ref: target.project_ref };
      if (input.action === 'FINGERPRINT') {
        const secret = await readSecret(SLOTS[input.slot]);
        stopIfAborted(signal);
        if (secret === undefined || secret === '') return reply('SECRET_NOT_SAVED', 409, { ...base, slot: input.slot });
        if (typeof secret !== 'string' || !TOKEN.test(secret)) return reply('SECRET_FORMAT_INVALID', 409, { ...base, slot: input.slot });
        const hash = await fingerprint(secret);
        stopIfAborted(signal);
        return reply('SECRET_FINGERPRINT_READY', 200, { ...base, slot: input.slot, credential_sha256: hash, grants_access: false });
      }
      const seen = new Set(); let restricted = false; let invalid = false;
      for (const slot of ['A', 'B']) {
        stopIfAborted(signal);
        const secret = await readSecret(SLOTS[slot]);
        stopIfAborted(signal);
        if (secret === undefined || secret === '') continue;
        if (typeof secret !== 'string' || !TOKEN.test(secret)) { invalid = true; continue; }
        const hash = await fingerprint(secret);
        stopIfAborted(signal);
        if (seen.has(hash)) continue;
        seen.add(hash);
        const upstream = await send(target.status_url, {
          method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${secret}` },
          body: JSON.stringify({ project_ref: target.project_ref }),
          redirect: 'error', cache: 'no-store', credentials: 'omit', signal,
        });
        stopIfAborted(signal);
        if (upstream.status !== 200) {
          void upstream.body?.cancel().catch(() => {});
          // Only credential denial warrants trying the second slot. An outage
          // or rate limit must not double load or expose a cached green result.
          if ([401, 403].includes(upstream.status)) { restricted ||= upstream.status === 403; continue; }
          if (upstream.status === 429) return reply('STATUS_RATE_LIMITED', 429, base);
          return reply('STATUS_UNAVAILABLE', 503, base);
        }
        const data = projectStatus(await boundedJson(upstream, 8192, signal), target.project_ref, now());
        stopIfAborted(signal);
        return reply('STATUS_READ', 200, { ...base, credential_slot: slot, connection: data });
      }
      if (seen.size) return reply(restricted ? 'STATUS_ACCESS_RESTRICTED' : 'STATUS_ACCESS_UNAVAILABLE', restricted ? 403 : 409, base);
      return reply(invalid ? 'SECRET_FORMAT_INVALID' : 'SECRET_NOT_SAVED', 409, base);
    };
    try { return await Promise.race([run().catch(() => reply('STATUS_UNAVAILABLE', 503)), interrupted]); }
    finally { clearTimeout(timer); request.signal.removeEventListener('abort', onAbort); }
  };
}

