import React, { createContext, useContext, useEffect, useState } from 'react';
import BosMemoryCard from '../../../../plugins/cloudbos-public-plugin/components/BosMemoryCard.jsx';
import SecretSetup from './SecretSetup.jsx';
import { connectionView, isAdmin, progressView, STAGES, WEBSITE } from './status-model.js';
import { pricingView, readPublicPricing } from './pricing-client.js';
import './BosStatusPage.css';

function useRead(loader, key, refresh) {
  const [result, setResult] = useState(null);
  useEffect(() => {
    let cancelled = false; const controller = new AbortController();
    setResult(null);
