import React, { useEffect, useRef, useState } from 'react';
import { connectionView, makeCandidate, readFingerprint, statusAccessReviewPrompt } from './status-model.js';

const browserCopy = text => navigator.clipboard.writeText(text);
export default function SecretSetup({ projectRef, client, copyText = browserCopy }) {
  const candidate = useRef(null);
  const operation = useRef(0);
  const [state, setState] = useState({ phase: 'idle' });
  const [message, setMessage] = useState('');
  useEffect(() => {
    operation.current++; candidate.current = null; setState({ phase: 'idle' }); setMessage('');
    return () => { operation.current++; candidate.current = null; };
  }, [projectRef, client]);
  async function prepare() {
    const seq = ++operation.current; candidate.current = null; setMessage(''); setState({ phase: 'checking' });
    try {
      const view = connectionView(await client.readStatus(), projectRef);
      let slot;
      if (view.code === 'SECRET_NOT_SAVED') slot = 'A';
      else if (view.code === 'STATUS_READ') slot = view.slot === 'A' ? 'B' : 'A';
      if (!slot) throw new Error('CURRENT_SLOT_UNVERIFIED');
      const existingHash = readFingerprint(await client.readFingerprint(slot), projectRef, slot);
      if (seq !== operation.current) return;
      if (existingHash) { setState({ phase: 'occupied', slot }); return; }
      const key = await makeCandidate();
      if (seq !== operation.current) return;
      candidate.current = { ...key, slot };
      setState({ phase: 'prepared', slot });
    } catch { if (seq === operation.current) setState({ phase: 'unavailable' }); }
  }
  async function copy(text, success) {
    const seq = operation.current;
    try { await copyText(text); if (seq === operation.current) setMessage(success); }
    catch { if (seq === operation.current) setMessage('Copy is unavailable. Open this app in a browser that supports secure clipboard access.'); }
  }
  async function verifySaved() {
    const key = candidate.current; if (!key) return;
    const seq = operation.current; setState({ phase: 'verifying', slot: key.slot }); setMessage('');
    try {
      const hash = readFingerprint(await client.readFingerprint(key.slot), projectRef, key.slot);
      if (seq !== operation.current || candidate.current !== key) return;
      if (hash !== key.hash) { setState({ phase: 'prepared', slot: key.slot }); setMessage(hash ? 'A different key is saved. Check the app and Secret name before trying again.' : 'The key has not been saved in Base44 yet.'); return; }
      candidate.current = null; // After exact comparison, retain only the hash.
      setState({ phase: 'verified', slot: key.slot, hash });
    } catch { if (seq === operation.current) { setState({ phase: 'prepared', slot: key.slot }); setMessage('The saved key could not be checked. Your current connection has not been changed.'); } }
  }
  async function resumeSaved() {
    const seq = ++operation.current; candidate.current = null; setMessage(''); setState({ phase: 'checking' });
    try {
      const view = connectionView(await client.readStatus(), projectRef);
      if (view.kind === 'denied') throw new Error('ACCESS_REQUIRED');
      const hashes = await Promise.all(['A', 'B'].map(async slot => ({ slot,
        hash: readFingerprint(await client.readFingerprint(slot), projectRef, slot) })));
      if (seq !== operation.current) return;
