  const working = ['checking', 'verifying'].includes(state.phase);
  const prepared = ['prepared', 'verifying'].includes(state.phase);
  return <section className="bos-page__card bos-page__setup" aria-labelledby="bos-setup-heading">
    <p className="bos-page__eyebrow">ONE-TIME STATUS SETUP</p><h2 id="bos-setup-heading">Connect your status page</h2>
    <p>A separate, limited key lets this page check BOS. Your existing build connection and app sign-in stay in place.</p>
    {['idle', 'checking', 'unavailable', 'occupied'].includes(state.phase) && <>
      <button type="button" className="bos-page__button" disabled={working} onClick={prepare}>{working ? 'Checking saved slots…' : 'Prepare status key'}</button>
      <button type="button" className="bos-page__text-button" disabled={working} onClick={resumeSaved}>Use an already saved key</button>
      {state.phase === 'unavailable' && <p role="status">A safe setup slot could not be verified. Ask BOS to check the status connection before replacing any saved key.</p>}
      {state.phase === 'occupied' && <p role="status">Slot {state.slot} already contains a saved key. Ask BOS to review it before replacing it. Nothing was overwritten.</p>}
    </>}
    {prepared && <ol className="bos-page__setup-steps">
      <li><strong>Open the secure form in Base44.</strong><p>Ask the builder for the Set secrets form for <code>BOS_APP_STATUS_{state.slot}</code>. Keep the key out of chat.</p>
        <button type="button" className="bos-page__text-button" onClick={() => copy(`Open the secure Set secrets form for BOS_APP_STATUS_${state.slot} in ${projectRef}. I will enter the key myself. Do not ask for the key in chat or change the other saved Secret.`, 'Setup request copied. Paste this request in Base44 chat first.')}>Copy setup request</button></li>
      <li><strong>Copy the key into that form and save.</strong><p>This page holds the key temporarily, so save it before leaving setup. Once saved in Base44, you can pause and return later.</p>
        <button type="button" className="bos-page__button" onClick={() => { const key = candidate.current; if (key) void copy(key.raw, 'Key copied. Paste it only into the secure Base44 form.'); }}>Copy key</button></li>
      <li><strong>Check that the saved key matches.</strong><p>BOS compares a fingerprint. The saved key itself is never sent back to this page.</p>
        <button type="button" className="bos-page__button" disabled={working} onClick={verifySaved}>{working ? 'Checking saved key…' : 'Check saved key'}</button></li>
    </ol>}
    {state.phase === 'verified' && <div role="status"><h3>Saved key matches</h3><p>The key is saved. BOS still needs your exact approval before this connection gains access.</p>
      <button type="button" className="bos-page__button" onClick={() => copy(statusAccessReviewPrompt(projectRef, state.slot, state.hash), 'Review request copied. Paste it in Base44 chat; it contains only the fingerprint.')}>Copy connection review request</button></div>}
    {state.phase === 'saved' && <div role="status"><h3>{state.hashes.length ? 'Saved keys found' : 'No saved keys found'}</h3>
      <p>{state.hashes.length ? 'You can continue after a pause. BOS will check whether the saved key is connected, awaiting approval or needs replacement. Its original value is not recovered.' : 'Prepare a status key to continue setup.'}</p>
      {state.hashes.map(item => <div key={item.slot} className="bos-page__saved-key"><span>Slot {item.slot}{item.slot === state.currentSlot ? ' · working connection' : ' · saved key'}</span>
        <button type="button" className="bos-page__text-button" disabled={item.slot === state.currentSlot}
          onClick={() => copy(statusAccessReviewPrompt(projectRef, item.slot, item.hash), 'Saved-key review request copied. Paste it in Base44 chat.')}>Copy review request for slot {item.slot}</button></div>)}
    </div>}
    {(prepared || ['verified', 'occupied', 'saved'].includes(state.phase)) && <button type="button" className="bos-page__text-button" onClick={cancel}>Clear local preparation</button>}
    {message && <p className="bos-page__notice" role="status">{message}</p>}
  </section>;
}

import { WEBSITE } from './status-model.js';

export const PRICING_URL = `${WEBSITE}data/bos-beta-pricing.json`;
const TIERS = ['STANDARD', 'PLUS', 'PRO', 'ENTERPRISE'];
const NAMES = ['Standard', 'Plus', 'Pro', 'Enterprise'];
const AVAILABILITY = ['CURRENT_CAPABILITIES', 'INVITE_ONLY', 'INVITE_ONLY_ATTENDED_LIMITS', 'CUSTOM_NOT_PRICED'];
const error = () => new Error('BOS_PRICING_UNAVAILABLE');

// Public list prices are display data, never account entitlement or a quote.
// New billing modes need a reviewed renderer; they cannot enable checkout here.
export function pricingView(input, now = Date.now()) {
  if (input?.schema !== 'BOS_PUBLIC_BETA_PRICE_LIST_V1' || input.currency !== 'AUD'
    || input.availability !== 'INVITE_ONLY_PRIVATE_BETA' || input.checkout_live !== false || input.grants_access !== false
    || !/^\d{4}-\d{2}-\d{2}\.\d+$/.test(input.version ?? '')
    || !/^\d{4}-\d{2}-\d{2}$/.test(input.effective_from ?? '') || !Number.isFinite(Date.parse(input.effective_from))
    || Date.parse(input.effective_from) > now || !Array.isArray(input.plans) || input.plans.length !== 4) throw error();
  const plans = TIERS.map((id, index) => {
    const rows = input.plans.filter(row => row?.id === id);
    if (rows.length !== 1) throw error();
    const row = rows[0];
    if (row.availability !== AVAILABILITY[index]
      || row.period !== (index === 0 ? 'ONGOING' : index === 3 ? null : 'MONTH')
      || (index === 3 ? row.amount_minor !== null : !Number.isSafeInteger(row.amount_minor) || row.amount_minor < 0 || row.amount_minor > 1000000)
      || (index === 0 && row.amount_minor !== 0)) throw error();
    const price = index === 3 ? 'Custom' : `A$${(row.amount_minor / 100).toLocaleString('en-AU', { maximumFractionDigits: 2, minimumFractionDigits: row.amount_minor % 100 ? 2 : 0 })}`;
    return { id, name: NAMES[index], price, period: index === 0 ? 'ongoing' : index === 3 ? 'Not yet priced' : '/ month' };
  });
  return { version: input.version, effectiveFrom: input.effective_from, plans };
}

export async function readPublicPricing({ signal, fetchImpl = globalThis.fetch } = {}) {
  const controller = new AbortController();
  const stop = () => controller.abort();
  if (signal?.aborted) throw error();
  signal?.addEventListener('abort', stop, { once: true });
  const timer = setTimeout(stop, 8000);
  let reader;
  try {
    const response = await fetchImpl(PRICING_URL, { method: 'GET', credentials: 'omit', referrerPolicy: 'no-referrer',
      cache: 'no-store', redirect: 'error', signal: controller.signal });
    if (!response.ok || response.headers.get('content-type')?.split(';')[0].trim() !== 'application/json'
      || !response.body || Number(response.headers.get('content-length') ?? 0) > 8192) throw error();
    reader = response.body.getReader(); const chunks = []; let size = 0;
    while (true) {
      const { value, done } = await reader.read(); if (done) break;
      size += value.length; if (size > 8192) throw error(); chunks.push(value);
    }
    if (controller.signal.aborted) throw error();
    const bytes = new Uint8Array(size); let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length; }
    const data = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
    pricingView(data);
    return data;
  } catch { throw error(); }
  finally { clearTimeout(timer); signal?.removeEventListener('abort', stop); await reader?.cancel().catch(() => {}); }
}

import { payload } from './status-model.js';

// Invoke through the existing app client. Each backend independently checks the
// current app user. The UI cannot choose a different app or send a role/tier.
export function createStatusPageClient(base44, { timeoutMs = 12000 } = {}) {
  if (!Number.isInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 12000) throw new Error('INVALID_CLIENT_TIMEOUT');
  async function invoke(name, args, { signal } = {}) {
    if (signal?.aborted) throw new Error('BOS_VIEW_UNAVAILABLE');
    let stop; let timer;
    const interrupted = new Promise((_, reject) => { stop = () => reject(new Error('BOS_VIEW_UNAVAILABLE')); });
    signal?.addEventListener('abort', stop, { once: true });
    timer = setTimeout(stop, timeoutMs);
    try { return payload(await Promise.race([base44.functions.invoke(name, args), interrupted])); }
