    const controller = new AbortController();
    setResult(null);
    Promise.resolve().then(() => loadSummary({ projectRef, signal: controller.signal }))
      .then(value => readMemorySummary(value, projectRef))
      .then(data => { if (!cancelled) setResult({ projectRef, loader: loadSummary, attempt, data }); })
      .catch(() => { if (!cancelled) setResult({ projectRef, loader: loadSummary, attempt, error: true }); });
    return () => { cancelled = true; controller.abort(); };
  }, [visible, projectRef, loadSummary, attempt]);

  if (!visible) return null;
  // Clear immediately on project/session/loader change, before effects run.
  const current = result?.projectRef === projectRef && result.loader === loadSummary && result.attempt === attempt ? result : null;
  const tab = TABS.find(value => value.key === active);
  const section = current?.data?.tabs[active];
  const unavailable = current?.error || section?.status === 'unavailable';
  const loading = !current;

  function onKeyDown(event, index) {
    let next;
    if (event.key === 'ArrowRight') next = (index + 1) % TABS.length;
    if (event.key === 'ArrowLeft') next = (index + TABS.length - 1) % TABS.length;
    if (event.key === 'Home') next = 0;
    if (event.key === 'End') next = TABS.length - 1;
    if (next === undefined) return;
    event.preventDefault();
    setActive(TABS[next].key);
    buttons.current[next]?.focus();
  }

  return (
    <section className="bos-memory" aria-labelledby={`${id}-title`}>
      <header className="bos-memory__header">
        <div><p className="bos-memory__eyebrow">BOS · YOUR APP</p><h2 id={`${id}-title`}>Your project, remembered</h2></div>
        <span className="bos-memory__readonly">Read only</span>
      </header>
      <div className="bos-memory__tabs" role="tablist" aria-label="Project memory">
        {TABS.map((value, index) => (
          <button key={value.key} ref={node => { buttons.current[index] = node; }} type="button"
            role="tab" id={`${id}-tab-${value.key}`} aria-controls={`${id}-panel-${value.key}`}
            aria-selected={active === value.key} tabIndex={active === value.key ? 0 : -1}
            onKeyDown={event => onKeyDown(event, index)} onClick={() => setActive(value.key)}>
            {value.label}
          </button>
        ))}
      </div>
      {TABS.filter(value => value.key !== active).map(value => <div hidden key={value.key} role="tabpanel"
        id={`${id}-panel-${value.key}`} aria-labelledby={`${id}-tab-${value.key}`} />)}
      <div key={`${projectRef}-${active}`} className="bos-memory__body" role="tabpanel" tabIndex={0}
        id={`${id}-panel-${active}`} aria-labelledby={`${id}-tab-${active}`} aria-busy={loading}>
        <p className="bos-memory__hint">{tab.hint}</p>
        {loading ? <p className="bos-memory__notice" role="status">Loading your saved summaries…</p>
          : unavailable ? <div className="bos-memory__notice" role="status"><h3>Summaries aren’t available right now.</h3><p>Try again to load your saved records.</p></div>
          : section.items.length === 0 ? <div className="bos-memory__notice"><h3>{tab.empty}</h3><p>{tab.detail}</p></div>
          : <ol className="bos-memory__list">{section.items.map((entry, index) => (
            <li key={`${entry.source}-${index}`}>
              <div className="bos-memory__item-heading"><h3>{entry.title}</h3>
                {entry.recorded_at && <time dateTime={entry.recorded_at}>{formatDate(entry.recorded_at)}</time>}
              </div>
              <p>{entry.summary}</p>
              {entry.outcome && <p className="bos-memory__outcome">{entry.outcome}</p>}
            </li>
          ))}</ol>}
        {section && section.total > section.items.length && <p className="bos-memory__hint">Showing the latest {section.items.length} of {section.total} saved summaries.</p>}
      </div>
      <footer className="bos-memory__footer">
        <span>{current?.data ? <>Snapshot saved <time dateTime={current.data.captured_at}>{formatDate(current.data.captured_at)}</time></> : 'From your app’s saved records'}</span>
        <button type="button" disabled={loading} onClick={() => setAttempt(value => value + 1)} aria-label="Refresh project memory">Refresh</button>
      </footer>
    </section>
  );
}

// Run against verified app records on the server or during a governed projection.
// This helper neither authenticates a caller nor grants access to source records.
export const MEMORY_SCHEMA = 'BOS_APP_MEMORY_SUMMARY_V1';
export const MEMORY_COMPONENT_VERSION = '1.0.0';
export const MEMORY_TABS = ['decisions', 'intentions', 'memory'];
const MAX_ITEMS = 30;

function text(value, limit = 480) {
  if (typeof value !== 'string') return '';
  const cleaned = value.replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
  return cleaned.length > limit ? `${cleaned.slice(0, limit - 1).trimEnd()}…` : cleaned;
}

function date(value) {
  return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(value)
    && Number.isFinite(Date.parse(value)) ? new Date(value).toISOString() : null;
}

function unavailable() { return { status: 'unavailable', items: [], total: null }; }

function item(row) {
  if (!row || typeof row !== 'object') return null;
  const title = text(row.title, 100);
  const summary = text(row.summary);
  const source = text(row.source, 160);
  if (!title || !summary || !source) return null;
  return {
    title, summary, source,
    outcome: text(row.outcome, 160),
    recorded_at: date(row.recorded_at),
  };
}

// Only supply deliberately selected, owner/admin-safe display fields here.
// Unknown fields (including raw records) are never copied into the response.
export function createMemorySummary(input, context) {
  if (context?.authenticated !== true || !['owner', 'admin'].includes(context.role)) {
    throw new Error('MEMORY_ACCESS_REQUIRED');
  }
  if (!input?.project_ref || context.project_ref !== input.project_ref) {
    throw new Error('MEMORY_PROJECT_MISMATCH');
  }
  const capturedAt = date(input.captured_at);
  if (!capturedAt) throw new Error('MEMORY_CAPTURE_TIME_REQUIRED');
  const tabs = {};
  for (const key of MEMORY_TABS) {
    const section = input.tabs?.[key];
    if (section?.status !== 'ready' || !Array.isArray(section.items)) {
      tabs[key] = unavailable();
      continue;
    }
    // Malformed data is not an empty history. Fail just the affected tab.
    const rows = section.items.map(item);
    if (rows.some(row => !row)) { tabs[key] = unavailable(); continue; }
    rows.sort((a, b) => (Date.parse(b.recorded_at) || 0) - (Date.parse(a.recorded_at) || 0));
    tabs[key] = { status: 'ready', items: rows.slice(0, MAX_ITEMS), total: rows.length };
  }
  return {
    schema: MEMORY_SCHEMA,
    project_ref: input.project_ref,
    captured_at: capturedAt,
    mode: 'snapshot',
    tabs,
  };
}

function sectionBullets(markdown, heading) {
  if (typeof markdown !== 'string') return null;
  const lines = markdown.split(/\r?\n/);
  const start = lines.findIndex(line => line.trim().toLowerCase() === `## ${heading}`);
  if (start < 0) return null;
  const values = [];
  for (const line of lines.slice(start + 1)) {
    if (/^##?\s/.test(line)) break;
    const match = line.match(/^\s*[-*]\s+(.+)$/);
    if (match) values.push(match[1]);
  }
  return values;
}

// Translate vocabulary used by the public pack without changing its claims.
function friendly(value) {
  return value.replace(/auth-gated/gi, 'sign-in protected')
    .replace(/governance artifacts/gi, 'BOS setup records')
    .replace(/exact readback/gi, 'checking the saved setup')
    .replace(/end-to-end/gi, 'from start to finish')
    .replace(/desktop-first/gi, 'designed for desktop');
}

// The public lean pack is separate from any private development pack.
// Read its exact, verified files outside this helper; never import them in React.
export function summarizeBase44Memory(records, context) {
  const state = records?.project_state;
  if (!state || state.project_binding_id !== records.project_ref) {
    throw new Error('MEMORY_PROJECT_MISMATCH');
  }
  const current = sectionBullets(records.build_intentions, 'current');
  const memory = [];
  const purpose = typeof records.project_spec === 'string'
    ? records.project_spec.match(/^Purpose:\s*(.+)$/m)?.[1] : null;
  if (purpose) memory.push({ title: 'What this app is for', summary: friendly(purpose), source: 'documents/PROJECT_SPEC.md' });
  const scope = sectionBullets(records.project_spec, 'in scope');
  if (scope) scope.forEach(summary => memory.push({ title: 'Project context', summary: friendly(summary), source: 'documents/PROJECT_SPEC.md' }));
  const stages = { PROTOTYPE: 'Prototype', PRIVATE_BETA: 'Private beta', PUBLIC_BETA: 'Public beta', PRODUCTION: 'Production' };
  if (stages[state.maturation_stage]) memory.push({
    title: 'Development stage', summary: stages[state.maturation_stage], source: 'governance/PROJECT_STATE.json',
  });

  // A planned activation is not a decision. Only explicitly curated decision
  // summaries may cross into the UI; raw ledger bodies are never forwarded.
  let decisions = null;
  if (Array.isArray(records.evidence_events)) {
    decisions = records.evidence_events
      .filter(event => event?.event === 'OWNER_DECISION_RECORDED'
        && event.project_binding_id === records.project_ref
        && event.display_summary?.audience === 'owner_admin')
      .map(event => ({
        title: event.display_summary.title,
        summary: event.display_summary.summary,
        outcome: event.display_summary.outcome,
        recorded_at: event.recorded_at,
        source: 'governance/EVIDENCE_LEDGER.jsonl',
      }));
  }
  const ready = items => items === null ? unavailable() : { status: 'ready', items };
  return createMemorySummary({
    project_ref: records.project_ref,
    captured_at: records.captured_at,
    tabs: {
      decisions: ready(decisions),
      intentions: ready(current?.map(summary => ({
        title: 'Current intention', summary: friendly(summary), source: 'governance/BUILD_INTENTIONS.md',
      })) ?? null),
      memory: ready(purpose && scope ? memory : null),
    },
  }, context);
}

// Validate again at the UI boundary. A mixed-up or malformed response must not
// leave the previous project's summaries on screen.
export function readMemorySummary(value, projectRef) {
  if (value?.schema !== MEMORY_SCHEMA || value.project_ref !== projectRef
    || value.mode !== 'snapshot' || !date(value.captured_at)) {
    throw new Error('MEMORY_RESPONSE_INVALID');
  }
  const tabs = {};
  for (const key of MEMORY_TABS) {
    const section = value.tabs?.[key];
    if (section?.status === 'unavailable') { tabs[key] = unavailable(); continue; }
    if (section?.status !== 'ready' || !Array.isArray(section.items)
      || section.items.length > MAX_ITEMS || !Number.isInteger(section.total)
      || section.total < section.items.length) throw new Error('MEMORY_RESPONSE_INVALID');
    const rows = section.items.map(item);
    if (rows.some(row => !row)) throw new Error('MEMORY_RESPONSE_INVALID');
    tabs[key] = { status: 'ready', items: rows, total: section.total };
  }
  return { schema: MEMORY_SCHEMA, project_ref: projectRef, captured_at: date(value.captured_at), mode: 'snapshot', tabs };
}

// Prepare a review artifact outside the target app. This command never installs,
// checkpoints, approves or alters app governance. The native builder performs
// any later writes only under the exact reviewed app-surface plan.
import { readFile, realpath, stat, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { resolve, relative, isAbsolute, dirname } from 'node:path';
import { pathToFileURL } from 'node:url';
import { summarizeBase44Memory } from '../plugins/cloudbos-public-plugin/scripts/app-memory-summary.mjs';
import { readSavedSnapshot, SNAPSHOT_SCHEMA } from '../OS/TEMPLATES/base44-public-app-status/snapshot/model.js';

export const SNAPSHOT_SOURCES = Object.freeze([
  'documents/AICONTROL.md', 'documents/PROJECT_SPEC.md',
  'governance/PROJECT_STATE.json', 'governance/BUILD_INTENTIONS.md',
  'governance/CAPABILITY_MANIFEST.json', 'governance/EVIDENCE_LEDGER.jsonl',
  'governance/BUILD_GATES.json', 'governance/GOVERNANCE_MANIFEST.json',
]);
const sha256 = value => createHash('sha256').update(value).digest('hex');
const inside = (root, path) => { const part = relative(root, path); return !part.startsWith('..') && !isAbsolute(part); };

// The caller supplies the independently reviewed expected hashes; they must
// never be learned from the same observed bytes merely to turn a mismatch green.
export function prepareSnapshotFromReadback({ review, files, revision, capturedAt }) {
  const hashes = review?.artifact_sha256;
  if (review?.schema !== 'BOS_BASE44_SNAPSHOT_SOURCE_REVIEW_V1'
    || !/^base44:[a-f0-9]{24}$/.test(review.project_ref ?? '')
    || !/^[a-f0-9]{40}$/.test(review.source_revision ?? '') || revision !== review.source_revision
    || !hashes || typeof hashes !== 'object' || Array.isArray(hashes)) throw new Error('SOURCE_REVIEW_REQUIRED');
  const paths = [...SNAPSHOT_SOURCES];
  if (Object.hasOwn(hashes, 'governance/SECURITY_BASELINE.md')) paths.push('governance/SECURITY_BASELINE.md');
  if (Object.keys(hashes).length !== paths.length || Object.keys(files).length !== paths.length
    || paths.some(path => !Object.hasOwn(hashes, path) || !Object.hasOwn(files, path)
      || !/^[a-f0-9]{64}$/.test(hashes[path] ?? '') || sha256(files[path]) !== hashes[path])) throw new Error('SOURCE_READBACK_MISMATCH');
  const decode = path => new TextDecoder('utf-8', { fatal: true }).decode(files[path]);
  const sourceReadback = { project_ref: review.project_ref, source_revision: revision,
    captured_at: capturedAt, artifact_sha256: Object.fromEntries(paths.sort().map(path => [path, hashes[path]])) };
  const records = {
    project_ref: review.project_ref, captured_at: capturedAt,
    project_state: JSON.parse(decode('governance/PROJECT_STATE.json')),
    project_spec: decode('documents/PROJECT_SPEC.md'), build_intentions: decode('governance/BUILD_INTENTIONS.md'),
    evidence_events: decode('governance/EVIDENCE_LEDGER.jsonl').split('\n').filter(line => line.trim()).map(line => JSON.parse(line)),
  };
  const snapshot = { schema: SNAPSHOT_SCHEMA, ...sourceReadback,
    source_readback_sha256: sha256(JSON.stringify(sourceReadback)),
    canonical_pointer_sha256: review.canonical_pointer_sha256,
    // Preserve reviewed observation identity and dates. Neither hashes nor this
    // projection script prove that an observation actually happened.
    stages: structuredClone(review.stages),
    memory: summarizeBase44Memory(records, { authenticated: true, role: 'admin', project_ref: review.project_ref }),
  };
  readSavedSnapshot(snapshot, review.project_ref, Date.parse(capturedAt));
  return snapshot;
}

export async function prepareSnapshotFile({ root: rootInput, reviewPath, reviewSha256, outputPath }) {
  if (!/^[a-f0-9]{64}$/.test(reviewSha256 ?? '')) throw new Error('EXACT_REVIEW_HASH_REQUIRED');
  const root = await realpath(resolve(rootInput));
  const output = resolve(outputPath);
  const outputParent = await realpath(dirname(output));
  if (inside(root, resolve(outputParent, relative(dirname(output), output)))) throw new Error('OUTPUT_MUST_BE_OUTSIDE_APP');
  const reviewBytes = await readFile(reviewPath);
  if (reviewBytes.byteLength > 32768 || sha256(reviewBytes) !== reviewSha256) throw new Error('SOURCE_REVIEW_HASH_MISMATCH');
  const review = JSON.parse(reviewBytes.toString('utf8'));
  const git = args => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  const revision = git(['rev-parse', 'HEAD']);
  if (git(['status', '--porcelain'])) throw new Error('CLEAN_SOURCE_READBACK_REQUIRED');
  const paths = [...SNAPSHOT_SOURCES];
  if (Object.hasOwn(review.artifact_sha256 ?? {}, 'governance/SECURITY_BASELINE.md')) paths.push('governance/SECURITY_BASELINE.md');
  const files = {}; let total = 0;
  for (const path of paths) {
    const file = await realpath(resolve(root, path));
    if (!inside(root, file)) throw new Error('SOURCE_PATH_OUTSIDE_APP');
    const info = await stat(file);
    if (!info.isFile() || info.size > 262144) throw new Error('BOUNDED_SOURCE_REQUIRED');
    files[path] = await readFile(file); total += files[path].byteLength;
    if (total > 1048576) throw new Error('BOUNDED_SOURCE_REQUIRED');
  }
  if (git(['rev-parse', 'HEAD']) !== revision || git(['status', '--porcelain'])) throw new Error('SOURCE_CHANGED_DURING_READBACK');
  const snapshot = prepareSnapshotFromReadback({ review, files, revision, capturedAt: new Date().toISOString() });
  const bytes = JSON.stringify(snapshot, null, 2) + '\n';
  // Exclusive creation also refuses symlink overwrite. Caller reviews the output
  // hash and adds these exact bytes to the native app-surface proposal.
  await writeFile(output, bytes, { flag: 'wx', mode: 0o600 });
  return { status: 'PREPARED_FOR_REVIEW', output, sha256: sha256(bytes),
    project_ref: review.project_ref, source_revision: revision, app_changed: false };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const [root, reviewPath, reviewSha256, outputPath, ...extra] = process.argv.slice(2);
  if (!root || !reviewPath || !outputPath || extra.length) {
    console.error('Usage: node scripts/prepare_base44_app_snapshot.mjs <app-root> <review.json> <expected-review-sha256> <new-output.json-outside-app>');
    process.exitCode = 1;
  } else {
    try { console.log(JSON.stringify(await prepareSnapshotFile({ root, reviewPath, reviewSha256, outputPath }), null, 2)); }
    catch (error) { console.error(/^[A-Z_]+$/.test(error?.message ?? '') ? error.message : 'SNAPSHOT_PREPARATION_FAILED'); process.exitCode = 1; }
  }
}
